/**
 * Perfect maze generator — recursive backtracker with an explicit stack.
 *
 * Grid of w x h cells. Each cell holds a wall bitmask:
 *   bit 0 (1) = North, bit 1 (2) = East, bit 2 (4) = South, bit 3 (8) = West
 * A set bit means "wall present"; carving removes the bits on both sides
 * of a passage, so every opening is mirrored in exactly two cells.
 */

export const N = 1;
export const E = 2;
export const S = 4;
export const W = 8;

const DIRS = [
  { bit: N, dx: 0, dy: -1, opp: S },
  { bit: E, dx: 1, dy: 0, opp: W },
  { bit: S, dx: 0, dy: 1, opp: N },
  { bit: W, dx: -1, dy: 0, opp: E },
] as const;

/** mulberry32 — small, fast, deterministic PRNG returning floats in [0, 1). */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface Maze {
  w: number;
  h: number;
  /** walls[i] bitmask for cell (i % w, (i / w) | 0). Starts at ALL_WALLS. */
  walls: Uint8Array;
}

const ALL_WALLS = N | E | S | W; // 15

/** Generate a perfect maze via iterative recursive backtracker. */
export function generateMaze(w: number, h: number, seed: number): Maze {
  if (w < 1 || h < 1) throw new RangeError(`bad dimensions ${w}x${h}`);
  const walls = new Uint8Array(w * h).fill(ALL_WALLS);
  const visited = new Uint8Array(w * h);
  const rng = mulberry32(seed);
  const stack: number[] = [];

  let cur = 0; // start at top-left cell
  visited[cur] = 1;
  stack.push(cur);

  while (stack.length > 0) {
    const cx = cur % w;
    const cy = (cur / w) | 0;

    // Collect unvisited neighbours.
    const options: number[] = [];
    for (let d = 0; d < 4; d++) {
      const { bit, dx, dy } = DIRS[d];
      const nx = cx + dx;
      const ny = cy + dy;
      if (nx >= 0 && nx < w && ny >= 0 && ny < h && !visited[ny * w + nx]) {
        options.push(d);
      }
    }

    if (options.length === 0) {
      // Dead end: backtrack.
      cur = stack.pop()!;
      continue;
    }

    // Randomised selection via the seeded RNG.
    const dirIdx = options[(rng() * options.length) | 0];
    const { bit, dx, dy, opp } = DIRS[dirIdx];
    const next = (cy + dy) * w + (cx + dx);

    walls[cur] &= ~bit;
    walls[next] &= ~opp;

    visited[next] = 1;
    stack.push(next);
    cur = next;
  }

  return { w, h, walls };
}

/** BFS from `start`, returning distances (-1 = unreached). */
export function bfsDistances(maze: Maze, start: number): Int32Array {
  const { w, h, walls } = maze;
  const dist = new Int32Array(w * h).fill(-1);
  dist[start] = 0;
  const queue = [start];
  for (let qi = 0; qi < queue.length; qi++) {
    const c = queue[qi];
    const cx = c % w;
    const cy = (c / w) | 0;
    for (let d = 0; d < 4; d++) {
      const { bit, dx, dy } = DIRS[d];
      if (walls[c] & bit) continue; // wall blocks the way
      const nx = cx + dx;
      const ny = cy + dy;
      if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
      const n = ny * w + nx;
      if (dist[n] !== -1) continue;
      dist[n] = dist[c] + 1;
      queue.push(n);
    }
  }
  return dist;
}

/** Index of the farthest cell from `start` (ties broken by lowest index). */
export function farthestCell(dist: Int32Array): number {
  let best = 0;
  for (let i = 1; i < dist.length; i++) {
    if (dist[i] > dist[best]) best = i;
  }
  return best;
}

/** Shortest path length between two cells (-1 if disconnected). */
export function shortestPathLength(maze: Maze, from: number, to: number): number {
  return bfsDistances(maze, from)[to];
}

/** Count open connections across the whole maze (each opening counted once per side => /2). */
export function countOpenings(maze: Maze): number {
  const { walls } = maze;
  let open = 0;
  for (const m of walls) {
    if (!(m & N)) open++;
    if (!(m & E)) open++;
    if (!(m & S)) open++;
    if (!(m & W)) open++;
  }
  return open / 2;
}

