import { E, N, S, W, type Maze } from "./maze.js";

/**
 * Render a maze with box-drawing characters.
 * Cell interiors are three spaces wide; walls are drawn on the shared grid.
 */
export function renderMaze(maze: Maze): string {
  const { w, h, walls } = maze;
  const lines: string[] = [];

  for (let y = 0; y < h; y++) {
    // Wall row above cells of this row.
    let top = "";
    for (let x = 0; x < w; x++) {
      const c = y * w + x;
      const m = walls[c];
      top += (m & N) && (m & W) ? "┌" : m & N ? "──" : m & W ? "│ " : "  ";
      if (m & N) top += "─";
      else if (x + 1 < w && !(walls[c + 1] & N) === false) {
        // neighbour shares this wall segment; keep it open only if both open
        top += (walls[c + 1] & N) || true ? " " : " ";
      } else top += " ";
      if (m & E) top += "┐";
    }
    lines.push(top);

    // Cell row.
    let mid = "";
    for (let x = 0; x < w; x++) {
      const c = y * w + x;
      const m = walls[c];
      mid += m & W ? "│" : " ";
      mid += "   ";
      if (m & E) mid += "│";
    }
    lines.push(mid);

    // Bottom wall row for the last grid row.
    if (y === h - 1) {
      let bot = "";
      for (let x = 0; x < w; x++) {
        const m = walls[y * w + x];
        bot += m & S ? "└───" : "    ";
        if (x === w - 1) bot += m & S ? "┘" : " ";
      }
      lines.push(bot);
    }
  }

  return lines.join("\n");
}

