import { E, N, S, W, type Maze } from "./maze.js";

/**
 * Render a maze with box-drawing characters.
 *
 * Approach: paint wall segments on a character canvas (each cell is one
 * interior space wide), then replace every intersection with the proper
 * corner/tee/cross glyph based on which of its four segments are present.
 */

/** Glyph lookup indexed by bitmask of present segments around an intersection. */
const GLYPHS = [
  " ", // no segments
  "╵", // up
  "╶", // right
  "└", // up + right
  "╷", // down
  "│", // up + down
  "┌", // right + down
  "├", // up + right + down
  "╴", // left
  "┘", // left + up
  "─", // left + right
  "┴", // left + up + right
  "┐", // left + down
  "┤", // left + up + down
  "┬", // left + right + down
  "┼", // all
];

export function renderMaze(maze: Maze): string {
  const { w, h, walls } = maze;
  const gw = 2 * w + 1;
  const gh = 2 * h + 1;
  const canvas = new Uint8Array(gw * gh); // bitmask of segments touching each point

  const add = (x: number, y: number, bit: number) => {
    canvas[y * gw + x] |= bit;
  };

  // Paint segments. Segment bits relative to an intersection:
  //   1 = goes up, 2 = goes right, 4 = goes down, 8 = goes left.
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const c = y * w + x;
      const m = walls[c];
      if (m & N) {
        add(2 * x, 2 * y, 4); // segment extends down to this corner
        add(2 * x + 1, 2 * y, 12); // horizontal run through midpoint
        add(2 * x + 2, 2 * y, 8);
      }
      if (m & W) {
        add(2 * x, 2 * y, 2);
        add(2 * x, 2 * y + 1, 5); // vertical run
        add(2 * x, 2 * y + 2, 1);
      }
    }
    // Outer south border.
    const mBottom = walls[y * w + w - 1];
    void mBottom;
  }
  for (let x = 0; x < w; x++) {
    if (walls[(h - 1) * w + x] & S) {
      add(2 * x, 2 * h, 1);
      add(2 * x + 1, 2 * h, 5);
      add(2 * x + 2, 2 * h, 2);
    }
  }
  for (let y = 0; y < h; y++) {
    if (walls[y * w + w - 1] & E) {
      add(2 * w, 2 * y, 8);
      add(2 * w, 2 * y + 1, 5);
      add(2 * w, 2 * y + 2, 4);
    }
  }

  let out = "";
  for (let y = 0; y < gh; y++) {
    for (let x = 0; x < gw; x++) {
      const bits = canvas[y * gw + x] & 15;
      out += bits === 0 ? " " : GLYPHS[bits];
    }
    out += "\n";
  }
  return out;
}

